import { opusJson } from "./anthropic";
import { aiModel } from "./models";
import { INTERVIEW_PREP_SYSTEM } from "./prompts";
import type { ResumeJson } from "./resumeParser";

// The interview prep pack for one job, saved as a `documents` row with type
// `interview_prep` (one per job). Generated by INTERVIEW_PREP_SYSTEM from the
// candidate's real sources only, then editable on Job Detail.

export const INTERVIEW_PREP_TYPE = "interview_prep";

export interface PrepStory {
  id: string;
  title: string;
  requirement: string;
  situation: string;
  action: string;
  result: string;
  /** One real metric from the sources, or null when none exists. */
  metric: string | null;
  /** Where the story comes from (resume role, saved answer, role chat). */
  source: string;
}

export interface PrepQuestion {
  id: string;
  question: string;
  /** The id of the story that answers it ("" if it no longer matches one). */
  story_id: string;
  angle: string;
}

export interface PrepGap {
  id: string;
  requirement: string;
  gap: string;
  how_to_handle: string;
}

export interface PrepAsk {
  id: string;
  question: string;
  why: string;
}

export interface InterviewPrep {
  stories: PrepStory[];
  questions: PrepQuestion[];
  gaps: PrepGap[];
  questions_to_ask: PrepAsk[];
}

export interface InterviewPrepInput {
  postingText: string;
  baseResume: ResumeJson;
  /** The approved tailored resume for this job, if there is one. */
  submittedResume: ResumeJson | null;
  extraAnswers: unknown;
  /** The saved role chat (formatCoachingNotes), or "". */
  coachingNotes: string;
}

function buildUserContent(input: InterviewPrepInput): string {
  const parts: string[] = [];
  parts.push(`JOB POSTING:\n${input.postingText.trim()}`);
  parts.push(`\n\nBASE RESUME (JSON) — full real history; factual ground truth:\n${JSON.stringify(input.baseResume)}`);
  if (input.submittedResume) {
    parts.push(
      `\n\nSUBMITTED RESUME (JSON) — tailored for this role; what the interviewers have read:\n${JSON.stringify(
        input.submittedResume,
      )}`,
    );
  }
  parts.push(`\n\nEXTRA ANSWERS (JSON):\n${JSON.stringify(input.extraAnswers ?? [])}`);
  if (input.coachingNotes.trim()) parts.push(`\n\n${input.coachingNotes.trim()}`);
  parts.push(`\n\nBuild the interview prep pack for this role.`);
  return parts.join("");
}

// Generous caps so a hand-edited pack can't grow without bound.
const MAX_ITEMS = 40;

function str(value: unknown): string {
  return typeof value === "string" ? value.trim() : value == null ? "" : String(value).trim();
}

function records(value: unknown): Record<string, unknown>[] {
  return Array.isArray(value)
    ? value.slice(0, MAX_ITEMS).map((v) => (v && typeof v === "object" ? (v as Record<string, unknown>) : {}))
    : [];
}

/** Keep a given id if it's usable and unique, else number a fresh one. */
function idMaker(prefix: string) {
  const used = new Set<string>();
  let n = 0;
  return (raw: unknown): string => {
    let id = str(raw);
    if (!id || used.has(id)) {
      do id = `${prefix}${++n}`;
      while (used.has(id));
    }
    used.add(id);
    return id;
  };
}

/**
 * Clean a pack from the model or from an edit: trims text, drops empty items,
 * makes ids unique, turns a blank metric into null, and points each question
 * at a real story (matching by title if the model used one instead of an id).
 */
export function normaliseInterviewPrep(raw: unknown): InterviewPrep {
  const r = (raw ?? {}) as Record<string, unknown>;

  const storyId = idMaker("s");
  const originalIds = new Map<string, string>();
  const stories: PrepStory[] = [];
  for (const s of records(r["stories"])) {
    const story = {
      title: str(s["title"]),
      requirement: str(s["requirement"]),
      situation: str(s["situation"]),
      action: str(s["action"]),
      result: str(s["result"]),
      metric: str(s["metric"]) || null,
      source: str(s["source"]),
    };
    if (!story.title && !story.situation && !story.action && !story.result) continue;
    const id = storyId(s["id"]);
    const given = str(s["id"]);
    if (given && !originalIds.has(given)) originalIds.set(given, id);
    stories.push({ id, ...story });
  }

  const byTitle = new Map(stories.map((s) => [s.title.toLowerCase(), s.id]));
  const findStory = (ref: string): string => {
    if (!ref) return "";
    if (stories.some((s) => s.id === ref)) return ref;
    return originalIds.get(ref) ?? byTitle.get(ref.toLowerCase()) ?? "";
  };

  const questionId = idMaker("q");
  const questions: PrepQuestion[] = records(r["questions"])
    .map((q) => ({
      question: str(q["question"]),
      story_id: findStory(str(q["story_id"])),
      angle: str(q["angle"]),
      rawId: q["id"],
    }))
    .filter((q) => q.question)
    .map(({ rawId, ...q }) => ({ id: questionId(rawId), ...q }));

  const gapId = idMaker("g");
  const gaps: PrepGap[] = records(r["gaps"])
    .map((g) => ({
      requirement: str(g["requirement"]),
      gap: str(g["gap"]),
      how_to_handle: str(g["how_to_handle"]),
      rawId: g["id"],
    }))
    .filter((g) => g.requirement || g.gap)
    .map(({ rawId, ...g }) => ({ id: gapId(rawId), ...g }));

  const askId = idMaker("a");
  const questions_to_ask: PrepAsk[] = records(r["questions_to_ask"])
    .map((a) => ({ question: str(a["question"]), why: str(a["why"]), rawId: a["id"] }))
    .filter((a) => a.question)
    .map(({ rawId, ...a }) => ({ id: askId(rawId), ...a }));

  return { stories, questions, gaps, questions_to_ask };
}

export async function runInterviewPrep(input: InterviewPrepInput): Promise<InterviewPrep> {
  const raw = await opusJson(INTERVIEW_PREP_SYSTEM, buildUserContent(input), aiModel("interviewPrep"));
  return normaliseInterviewPrep(raw);
}
